import java.util.List;
import org.apache.lucene.geo.Polygon;
import org.apache.lucene.geo.Tessellator;
import org.apache.lucene.document.ShapeField;

public class Debug {
  public static void main(String[] args) {
    double[] lons = new double[] {-0.001, -0.001, 0.001, 0.001, -0.001};
    double[] lats = new double[] {1e-10, 0, -1e-10, 0, 1e-10};
    Polygon polygon = new Polygon(lats, lons);
    List<Tessellator.Triangle> tess = Tessellator.tessellate(polygon, false);
    System.out.println("num triangles=" + tess.size());
    ShapeField.DecodedTriangle dt = new ShapeField.DecodedTriangle();
    for (int i = 0; i < tess.size(); i++) {
      Tessellator.Triangle t = tess.get(i);
      System.out.println("T" + i + " raw:");
      for (int v = 0; v < 3; v++) {
        System.out.println("  v" + v + " x=" + t.getX(v) + " y=" + t.getY(v)
            + " encX=" + t.getEncodedX(v) + " encY=" + t.getEncodedY(v)
            + " edge=" + t.isEdgefromPolygon(v));
      }
      byte[] bytes = new byte[7 * ShapeField.BYTES];
      ShapeField.encodeTriangle(bytes,
          t.getEncodedY(0), t.getEncodedX(0), t.isEdgefromPolygon(0),
          t.getEncodedY(1), t.getEncodedX(1), t.isEdgefromPolygon(1),
          t.getEncodedY(2), t.getEncodedX(2), t.isEdgefromPolygon(2));
      ShapeField.decodeTriangle(bytes, dt);
      System.out.println("  decoded type=" + dt.type + " a=(" + dt.aX + "," + dt.aY + ") ab=" + dt.ab
          + " b=(" + dt.bX + "," + dt.bY + ") bc=" + dt.bc
          + " c=(" + dt.cX + "," + dt.cY + ") ca=" + dt.ca);
    }
  }
}

